/**
 * Regenerate the browser libraries that lesson demos receive inline
 * (src/core/vendor/floating-ui-v1.ts and lucide-v1.ts).
 *
 *   mkdir /tmp/demo-libs && cd /tmp/demo-libs
 *   npm pack @floating-ui/core@1.7.3 @floating-ui/dom@1.7.4 lucide@1.17.0
 *   for p in *.tgz; do mkdir "${p%.tgz}" && tar -xzf "$p" -C "${p%.tgz}"; done
 *   node scripts/vendor-demo-libraries.mjs /tmp/demo-libs
 *
 * Every file must match the sha256 pinned in src/core/vendor/demo-libraries.json.
 * Each library's full license text is embedded ahead of its code, and the
 * license files are copied next to the modules.
 */
import { createHash } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const vendor = path.join(root, "src/core/vendor");
const packs = process.argv[2];
if (!packs) throw new Error("usage: node scripts/vendor-demo-libraries.mjs <dir with extracted npm packs>");
const manifest = JSON.parse(fs.readFileSync(path.join(vendor, "demo-libraries.json"), "utf8"));

function packageDir(name, version) {
	for (const entry of fs.readdirSync(packs)) {
		const dir = path.join(packs, entry, "package");
		if (!fs.existsSync(path.join(dir, "package.json"))) continue;
		const pkg = JSON.parse(fs.readFileSync(path.join(dir, "package.json"), "utf8"));
		if (pkg.name === name && pkg.version === version) return dir;
	}
	throw new Error(`no extracted pack for ${name}@${version} in ${packs}`);
}

const modules = new Map();
for (const lib of manifest.libraries) {
	const dir = packageDir(lib.name, lib.version);
	const code = fs.readFileSync(path.join(dir, lib.file), "utf8");
	const digest = createHash("sha256").update(code).digest("hex");
	if (digest !== lib.sha256) throw new Error(`${lib.name}@${lib.version} ${lib.file}: sha256 ${digest} does not match the manifest`);
	const license = fs.readFileSync(path.join(dir, "LICENSE"), "utf8").trim();
	fs.writeFileSync(path.join(vendor, lib.licenseFile), license + "\n");
	const body = code.replace(/\n\/\/# sourceMappingURL=\S+\s*$/, "\n");
	const notice = `/*!\n${lib.name} ${lib.version}\n\n${license.replace(/\*\//g, "* /")}\n*/\n`;
	if (!modules.has(lib.module)) modules.set(lib.module, []);
	modules.get(lib.module).push({ lib, source: notice + body });
}

const exportName = { "floating-ui-v1.ts": "FLOATING_UI_RUNTIME", "lucide-v1.ts": "LUCIDE_RUNTIME" };
for (const [file, parts] of modules) {
	const label = parts.map(({ lib }) => `${lib.name} ${lib.version} (${lib.license})`).join(", ");
	const source = parts.map((part) => part.source).join("\n");
	fs.writeFileSync(
		path.join(vendor, file),
		`// Generated by scripts/vendor-demo-libraries.mjs from ${label}. Full notices accompany the runtime below.\nexport const ${exportName[file]} = ${JSON.stringify(source)};\n`,
	);
	console.log(`${file}: ${source.length} chars`);
}
